PRAGMA foreign_keys = ON;
CREATE TABLE sku (sku_id TEXT PRIMARY KEY, sku_name TEXT NOT NULL, category TEXT NOT NULL, unit_cost REAL NOT NULL CHECK(unit_cost>=0), unit_price REAL NOT NULL CHECK(unit_price>=0), is_discontinued INTEGER NOT NULL, launch_date TEXT NOT NULL, lifecycle_status TEXT NOT NULL CHECK(lifecycle_status IN ('ACTIVE','DISCONTINUED')));
CREATE TABLE store (store_id TEXT PRIMARY KEY, store_name TEXT NOT NULL, region TEXT NOT NULL, daily_storage_capacity_units INTEGER NOT NULL CHECK(daily_storage_capacity_units>=0));
CREATE TABLE supplier (supplier_id TEXT PRIMARY KEY, supplier_name TEXT NOT NULL, active INTEGER NOT NULL);
CREATE TABLE supplier_sku (supplier_sku_id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES supplier, sku_id TEXT NOT NULL REFERENCES sku, pack_size INTEGER NOT NULL CHECK(pack_size>0), moq_units INTEGER NOT NULL CHECK(moq_units>0), supplier_capacity_units INTEGER NOT NULL CHECK(supplier_capacity_units>=0), effective_from TEXT NOT NULL, effective_to TEXT, UNIQUE(supplier_id,sku_id,effective_from));
CREATE TABLE sales_history (sale_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store, sku_id TEXT NOT NULL REFERENCES sku, sale_date TEXT NOT NULL, units_sold INTEGER NOT NULL CHECK(units_sold>=0), promotion_flag INTEGER NOT NULL, stockout_flag INTEGER NOT NULL, unit_price REAL NOT NULL, UNIQUE(store_id,sku_id,sale_date));
CREATE TABLE inventory_snapshot (snapshot_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store, sku_id TEXT NOT NULL REFERENCES sku, snapshot_date TEXT NOT NULL, on_hand_units INTEGER NOT NULL CHECK(on_hand_units>=0), on_order_units INTEGER NOT NULL CHECK(on_order_units>=0), reserved_units INTEGER NOT NULL CHECK(reserved_units>=0));
CREATE TABLE lead_time_observation (lead_time_observation_id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES supplier, sku_id TEXT NOT NULL REFERENCES sku, observed_days INTEGER NOT NULL, observation_date TEXT NOT NULL, is_valid INTEGER NOT NULL);
CREATE TABLE forecast (forecast_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store, sku_id TEXT NOT NULL REFERENCES sku, forecast_as_of TEXT NOT NULL, forecast_daily_units REAL NOT NULL, forecast_horizon_units REAL NOT NULL);
CREATE TABLE reorder_policy (policy_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store, sku_id TEXT NOT NULL REFERENCES sku, safety_stock_units INTEGER NOT NULL, reorder_point_units INTEGER NOT NULL, effective_from TEXT NOT NULL);
CREATE TABLE purchase_recommendation (purchase_recommendation_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store, sku_id TEXT NOT NULL REFERENCES sku, recommended_order_units INTEGER NOT NULL, decision TEXT NOT NULL, exception_code TEXT NOT NULL, created_at TEXT NOT NULL);
